"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["1905"],{2366(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.rotulo_tamanho","status":422,"titulo":"O r\xf3tulo do item excede o tamanho m\xe1ximo"},"descricao":{"codigo":"uniplus.item_formulario.rotulo_tamanho","requisitos":[],"oQueAconteceu":["O `rotulo` de um item do formul\xe1rio, ou de um campo de grupo, tem mais de 300 caracteres depois de aparado. A mensagem \xe9 \\"O r\xf3tulo do item deve ter no m\xe1ximo 300 caracteres.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].rotulo` ou, no campo de um grupo, `grupos[g].subitens[j].rotulo`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Cada item recusado tem a pr\xf3pria entrada, junto das demais recusas da forma do item, e o item de forma recusada n\xe3o segue para a confer\xeancia contra o cat\xe1logo de fatos. Nada \xe9 gravado. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Encurte o `rotulo` para at\xe9 300 caracteres. O texto longo que explica o campo cabe na ajuda do campo, e n\xe3o no r\xf3tulo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);